def validate(data: dict) -> dict:
    if data.get("category") not in ALLOWED:
        raise ValueError(f"অবৈধ category: {data.get('category')!r}")
    if data.get("confidence") not in ("high", "medium", "low"):
        raise ValueError("অবৈধ confidence")
    if not isinstance(data.get("needs_human"), bool):
        raise ValueError("needs_human boolean নয়")
    # ব্যবসায়িক নিয়ম: low confidence হলে মানুষ লাগবেই
    if data["confidence"] == "low" and not data["needs_human"]:
        raise ValueError("low confidence হলে needs_human=true হতে হবে")
    return data

SAFE_DEFAULT = {"category": "OTHER", "confidence": "low", "needs_human": True}

def classify(ticket: str, max_tries: int = 3) -> dict:
    messages = [{"role": "user", "content": f"<ticket>{ticket}</ticket>"}]
    for attempt in range(1, max_tries + 1):
        r = client.messages.create(
            model=MODEL, max_tokens=300, system=JSON_SYSTEM, messages=messages,
            output_config={"format": {"type": "json_schema", "schema": SCHEMA}})
        if r.stop_reason in ("max_tokens", "refusal"):
            print(f"  চেষ্টা {attempt}: stop_reason={r.stop_reason}; fallback")
            break
        text = "".join(b.text for b in r.content if b.type == "text")
        try:
            return validate(json.loads(text))
        except ValueError as e:        # JSONDecodeError-ও ValueError-এর সন্তান
            print(f"  চেষ্টা {attempt} ব্যর্থ: {e}")
            messages += [{"role": "assistant", "content": text},
                         {"role": "user", "content": f"আগের উত্তর অবৈধ: {e}. বৈধ JSON দাও।"}]
    return dict(SAFE_DEFAULT, _fallback=True)

for t, exp in TESTS:
    print(exp, "->", classify(t))
